FILE = "tems-children-of-blood-and-bone-soundtrack.html"
TITLE = "Tems is curating the Children of Blood and Bone soundtrack"
TAG = "The Wrap"
H1 = "Tems is curating the Children of Blood and Bone soundtrack"
DEK = "She's the executive music producer on Paramount's African fantasy epic. This week she named the artists on it, and her own lead single is out on 20 November."
META = "The Wrap · Continental · 13 Nov 2026 · 3 min read"
LEAD = ("img/wr-tems-cobab.jpg", "Tems, photographed for EE72's Fall 2026 digital cover", "Campbell Addy for EE72")

BODY = [
("p", "Tems isn't just singing on the <em>Children of Blood and Bone</em> soundtrack. She's in charge of it. As executive music producer and curator, she's shaping the whole album for Paramount Pictures' adaptation of Tomi Adeyemi's bestselling fantasy novel, which reaches cinemas on 15 January 2027."),
("p", "Until now, fans only had the job title to go on. This week Tems announced the soundtrack's lead single and named everyone else on it."),
("h2", "The single", "African ", "Love Story"),
("p", "The first song is “African Love Story”, which Tems wrote and performs herself. It's out on Friday 20 November through RCA Records, and pre-saves are already open. If you can't wait, pieces of it play through the film's new trailer, released the same day as the announcement."),
("h2", "The lineup", "Who's ", "on it"),
("p", "Eleven acts join her: Burna Boy, Ayra Starr, Fireboy DML, BNXN, Kold AF, Obongjayar, Moelogo, Daecolm, Pa Salieu, Show Dem Camp and Moonchild Sanelly. Burna Boy has a second job on the film too, as its executive music consultant."),
("p", "Ayra Starr is doing double duty as well. Besides her place on the soundtrack, she's part of the film's cast."),
("h2", "How we got here", "Announced ", "in July"),
("p", "Tems' role was first made public on 28 July 2026, when director Gina Prince-Bythewood announced it at the film's trailer launch event in New York. Tems' manager, Muyiwa Awoniyi, confirmed it on X shortly after and promised three brand-new Tems songs for the film."),
("p", "Prince-Bythewood has also said Tems is the first woman to executive produce a film soundtrack at this scale."),
("p", "It's the latest first on a long list. Tems already has two Grammys, and her feature on Future’s “Wait for U”, alongside Drake, made her the first African female artist with an RIAA Diamond-certified single in the US."),
("h2", "The film", "Welcome ", "to Orïsha"),
("p", "<em>Children of Blood and Bone</em> is set in Orïsha, a world built on the Yoruba Orisha tradition. South Africa's Thuso Mbedu plays Zélie Adebola, a young woman fighting to bring magic back to her people. The cast also includes Viola Davis, Idris Elba, Cynthia Erivo, Chiwetel Ejiofor and Lashana Lynch."),
("p", "The film opens in cinemas, IMAX included, in January. Its music gets here first: “African Love Story” is out on 20 November."),
]

